import{_ as a,o as s,c as e,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"[决策] Redis 与 MySQL 分别存什么","description":"","frontmatter":{},"headers":[],"relativePath":"tech-system/industrial-digitalization/decisions/03-redis-vs-mysql.md","filePath":"tech-system/industrial-digitalization/decisions/03-redis-vs-mysql.md"}'),d={name:"tech-system/industrial-digitalization/decisions/03-redis-vs-mysql.md"};function n(r,t,l,h,o,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="决策-redis-与-mysql-分别存什么" tabindex="-1"><code>[决策]</code> Redis 与 MySQL 分别存什么 <a class="header-anchor" href="#决策-redis-与-mysql-分别存什么" aria-label="Permalink to “[决策] Redis 与 MySQL 分别存什么”">​</a></h1><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>状态</td><td>🔵 设计中</td></tr><tr><td>类型</td><td><code>[决策]</code></td></tr><tr><td>项目</td><td>Mini MES V0</td></tr><tr><td>证据</td><td>待 Lab 001</td></tr></tbody></table><hr><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>设备数据同时有「最新一眼」和「事后可查」两种用法。</p><h2 id="判断" tabindex="-1">判断 <a class="header-anchor" href="#判断" aria-label="Permalink to “判断”">​</a></h2><table tabindex="0"><thead><tr><th>存储</th><th>存什么</th><th>不存什么</th></tr></thead><tbody><tr><td><strong>Redis</strong></td><td>设备在线状态、最新测点快照、短 TTL 会话/限流</td><td>不当事后审计库；不替代历史</td></tr><tr><td><strong>MySQL</strong></td><td>设备档案、点表配置、历史采样（V0 可先落同一库表）、后续工单等业务</td><td>不扛超高写入的无限明细（那是以后 TSDB 的事）</td></tr></tbody></table><p>读写路径（V0）：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Gateway 上报</span></span>
<span class="line"><span>  → 写 Redis（最新值 / 在线）</span></span>
<span class="line"><span>  → 异步或同步写 MySQL（历史采样 + 业务）</span></span>
<span class="line"><span>  → 监控页：列表走 Redis，曲线走 MySQL</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="为何-v0-仍要-redis" tabindex="-1">为何 V0 仍要 Redis <a class="header-anchor" href="#为何-v0-仍要-redis" aria-label="Permalink to “为何 V0 仍要 Redis”">​</a></h2><ul><li>监控页高频刷「在不在线、当前值」时，避免每次打库</li><li>为以后告警判定「当前状态」留统一入口</li></ul><p>若 Lab 001 设备量极小且无压力，可短期只用 MySQL，但模型上仍按上表分职责，避免业务表被当成缓存滥用。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h2><p><strong>Redis = 当前态；MySQL = 真相与历史（V0）。</strong> 分工先于「要不要上更多中间件」。</p>`,14)])])}const m=a(d,[["render",n]]);export{b as __pageData,m as default};
